    ],
    "lacunas": [],
    "motivo": "Término da linha base declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f7ff82", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "Dossiê reduzido a 1 dia, mas não pode iniciar antes de D8: termina em D9. Inspeção, dependente também do ensaio que termina em D9, ocorre de D9 a D10; o marco final ocorre em D10.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "exato",
    "valor": -2,
    "direcao": "reducao",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_f7ff82", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "D10 novo menos D12 da linha base: antecipação de 2 dias corridos.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "Custo total da linha base declarado como R$1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f7ff82", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "O aviso não tem custo direto; as parcelas fixas não variam com o prazo e a política sem crédito mantém o apoio no valor contratado de R$650,00.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {"fonte_id": "f_f7ff82", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": [],
    "motivo": "O custo novo permanece igual ao custo base; não há ajuste de custo expresso no aviso.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A redução do dossiê de 3 para 1 dia não supera a restrição de início em D8. O dossiê e o ensaio terminam em D9, permitindo inspeção e marco final em D10, contra D12 na linha base. O prazo menor não altera parcelas fixas nem o apoio contratado, que não concede crédito por antecipação."
}

